#!/usr/bin/env node
"use strict";
// Rehkitzrettung Hegering Hittfeld - eigenstaendiger PWA-Appsymbol-Installer.
// In Projektroot ablegen; keine weiteren Dateien notwendig.
// --check = nur lesen/pruefen; ohne Argumente = installieren und Backup anlegen.
const fs = require("node:fs");
const path = require("node:path");
const root = process.cwd();
const checkOnly = process.argv.includes("--check");
const ASSETS = {
  "public/icon-192.png": "",
  "public/icon-512.png": "",
  "public/rehkitz-app-192.png": "",
  "public/rehkitz-app-512.png": "",
  "public/rehkitz-app-maskable-512.png": "",
  "app/apple-icon.png": "",
  "app/favicon.ico": "",

};
function fail(message) { console.error("ABBRUCH: " + message); process.exit(1); }
function getFile(rel) { return path.join(root,...rel.split("/")); }
function findClosingArray(text, opening) {
  let depth = 0, quoted = null, escaped = false;
  for (let i = opening; i < text.length; i++) {
    const c = text[i];
    if (quoted) {
      if (escaped) { escaped = false; continue; }
      if (c === "\\") { escaped = true; continue; }
      if (c === quoted) quoted = null;
      continue;
    }
    if (c === '"' || c === "'" || c === "`" ) { quoted = c; continue; }
    if (c === "[") depth++;
    if (c === "]") { depth--; if (depth === 0) return i; }
  }
  return -1;
}
function patchManifest(input) {
  let out = input;
  const replacements = [
    ["icon-192.png", "rehkitz-app-192.png"],
    ["icon-512.png", "rehkitz-app-512.png"],
  ];
  for (const [oldName, newName] of replacements) {
    if (out.includes('"/' + newName + '"') || out.includes("'/"+newName+"'")) continue;
    const re = new RegExp('(["\\x27])/' + oldName.replaceAll('.','\\.') + '\\1');
    if (!re.test(out)) throw new Error("Manifest-Icon /"+oldName+" nicht gefunden. Bitte Manifest pruefen; keine Dateien veraendert.");
    out = out.replace(re, '"/' + newName + '"');
  }
  if (!out.includes("rehkitz-app-maskable-512.png")) {
    const m = /\bicons\s*:\s*\[/.exec(out);
    if (!m) throw new Error("Keine icons-Liste in app/manifest.ts gefunden. Keine Dateien veraendert.");
    const start = m.index + m[0].lastIndexOf("[");
    const end = findClosingArray(out, start);
    if (end < 0) throw new Error("icons-Liste in app/manifest.ts nicht lesbar. Keine Dateien veraendert.");
    const insert = '\n      {\n        src: "/rehkitz-app-maskable-512.png",\n        sizes: "512x512",\n        type: "image/png",\n        purpose: "maskable",\n      },\n    ';
    out = out.slice(0,end) + insert + out.slice(end);
  }
  return out;
}
if (!fs.existsSync(getFile("package.json")) || !fs.existsSync(getFile("app/manifest.ts"))) {
  fail("Bitte aus dem Next.js-Projektordner starten (mit package.json und app/manifest.ts), z.B. C:\\Projekte\\rehkitzrettung.");
}
let nextManifest;
try {
  const original = fs.readFileSync(getFile("app/manifest.ts"),"utf8");
  nextManifest = patchManifest(original);
} catch(e) { fail(e.message); }
const paths = Object.keys(ASSETS).concat(["app/manifest.ts"]);
console.log("PWA-Appsymbol: Drohne und Rehkitz");
console.log("Projekt: " + root);
console.log("Betroffene Dateien:");
for (const rel of paths) console.log("  " + rel + (fs.existsSync(getFile(rel)) ? " (wird gesichert)" : " (neu)"));
if (checkOnly) {
  console.log("VORPRUEFUNG OK. Keine Dateien veraendert.");
  process.exit(0);
}
const timestamp = new Date().toISOString().replace(/[:.]/g,"-");
const backup = path.join(path.dirname(root), path.basename(root) + "-pwa-backup-" + timestamp);
const overwritten = [];
const created = [];
try {
  fs.mkdirSync(backup, {recursive:true});
  // Alle bisherigen Dateien vor dem ersten Eingriff sichern.
  for (const rel of paths) {
    const p = getFile(rel);
    if (fs.existsSync(p)) {
      const dest = path.join(backup,...rel.split("/"));
      fs.mkdirSync(path.dirname(dest),{recursive:true});
      fs.copyFileSync(p,dest);
      overwritten.push(rel);
    } else created.push(rel);
  }
  for (const [rel,encoded] of Object.entries(ASSETS)) {
    const target = getFile(rel);
    fs.mkdirSync(path.dirname(target),{recursive:true});
    fs.writeFileSync(target,Buffer.from(encoded,"base64"));
  }
  fs.writeFileSync(getFile("app/manifest.ts"),nextManifest,"utf8");
  console.log("INSTALLATION OK.");
  console.log("Backup: " + backup);
  console.log("Jetzt npm run build ausfuehren; erst nach erfolgreichem Build Git-Commit/Push.");
  console.log("Hinweis: Bereits installierte PWAs zeigen das neue Symbol je nach Geraet erst nach Neuininstallation.");
} catch(e) {
  console.error("Fehler: "+e.message+" - stelle alte Dateien aus Backup wieder her.");
  for (const rel of overwritten) {
    try {fs.copyFileSync(path.join(backup,...rel.split("/")),getFile(rel));} catch {}
  }
  for (const rel of created) {
    try {fs.rmSync(getFile(rel),{force:true});} catch {}
  }
  fail("Installation fehlgeschlagen, Ruecksetzung versucht. Backup: "+backup);
}
